// service
async getEmail(id: number) {
  const user = await this.repo.findOne({ where: { id } });
  return user.email; // prod: throws on a missing id
}

// test
repoMock.findOne.mockResolvedValue({ id: 1, email: 'a@b.com' });
expect(await service.getEmail(1)).toBe('a@b.com'); // GREEN

The real repo.findOne returns null when no row matches. Why did this green test let the prod null-deref through?

