// Mock the EmailService (boundary you don't own); FAKE the repo (you own it).
class FakeUserRepo {
  private rows = new Map<number, User>();
  async findOne({ where: { id, email } }: any) {
    if (id != null) return this.rows.get(id) ?? null;          // null on miss, like reality
    return [...this.rows.values()].find((u) => u.email === email) ?? null;
  }
  async save(u: User) {
    const dup = [...this.rows.values()].find((r) => r.email === u.email && r.id !== u.id);
    if (dup) throw new Error('duplicate key value violates unique constraint'); // enforce UNIQUE
    this.rows.set(u.id, u);
    return u;
  }
}
const mailMock = { send: jest.fn() };
const fakeRepo = new FakeUserRepo();

const moduleRef = await Test.createTestingModule({ providers: [UsersService] })
  .overrideProvider(getRepositoryToken(User)).useValue(fakeRepo) // fake, not dumb mock
  .overrideProvider(MailService).useValue(mailMock)               // mock the boundary
  .compile();

// now: getEmail(9999) hits null and you can assert the NotFoundException;
// creating two users with the same email throws — the duplicate path is testable.

Why: the EmailService is an external boundary — you can't hit a real provider in a unit test and its contract is stable, so a mock is correct and fast. The repository is YOURS and is exactly the part that drifts, so a fake that honours the contract (null on miss, UNIQUE on save) restores the two paths a dumb mock froze. For full confidence, add a thin real-DB integration test that pins the actual TypeORM/Postgres contract.

