// Мокни EmailService (граница, которой не владеешь); ЗАФЕЙКАЙ репо (им владеешь).
class FakeUserRepo {
  private rows = new Map<number, User>();
  async findOne({ where: { id, email } }: any) {
    if (id != null) return this.rows.get(id) ?? null;          // null на промахе, как в реальности
    return [...this.rows.values()].find((u) => u.email === email) ?? null;
  }
  async save(u: User) {
    const dup = [...this.rows.values()].find((r) => r.email === u.email && r.id !== u.id);
    if (dup) throw new Error('duplicate key value violates unique constraint'); // обеспечь UNIQUE
    this.rows.set(u.id, u);
    return u;
  }
}
const mailMock = { send: jest.fn() };
const fakeRepo = new FakeUserRepo();

const moduleRef = await Test.createTestingModule({ providers: [UsersService] })
  .overrideProvider(getRepositoryToken(User)).useValue(fakeRepo) // фейк, а не тупой мок
  .overrideProvider(MailService).useValue(mailMock)               // мокни границу
  .compile();

// теперь: getEmail(9999) попадает в null, и можно проверить NotFoundException;
// создание двух пользователей с одним email выбрасывает — ветка дубликата тестируема.

Почему: EmailService — внешняя граница: настоящий провайдер не подёргаешь в юнит-тесте, а его контракт стабилен, так что мок верен и быстр. Репозиторий — ТВОЙ и ровно та часть, что дрейфует, так что фейк, чтущий контракт (null на промахе, UNIQUE на save), восстанавливает две ветки, которые тупой мок заморозил. Для полной уверенности добавь тонкий интеграционный тест на настоящей БД, прикалывающий реальный контракт TypeORM/Postgres.
